/**
 * Session close middleware.
 * Customer Close/CLS → end session + notify the company desk.
 * Desk Close/CLS → end session silently (no customer notice).
 */
const { Settings, ChatSessions, MessageLog } = require('../../models');

function buildCustomerCloseNotice(session) {
  const code = session.session_code || String(session.id);
  const tpl = Settings.get('chat_close_message');
  if (tpl && String(tpl).trim()) {
    return String(tpl)
      .replace(/\{\{\s*session_code\s*\}\}/gi, code)
      .replace(/\{\{\s*customer_phone\s*\}\}/gi, session.customer_phone || '')
      .replace(/\{\{\s*company\s*\}\}/gi, session.company_name || '');
  }
  return (
    `Customer ended the chat [#${code}].\n` +
    `Session closed.`
  );
}

/**
 * @param {object} whatsapp - WhatsAppService
 * @param {object} session
 * @param {{ closedBy?: string }} [opts]
 */
async function closeSessionWithNotify(whatsapp, session, opts = {}) {
  const closedBy = opts.closedBy || 'customer';
  if (!session?.id) return { ok: false, reason: 'no_session' };

  ChatSessions.close(session.id);
  console.log(
    `[SessionClose] #${session.id}[${session.session_code}] closed by ${closedBy}`
  );

  // Target: user X Close/CLS → forward close notification to company
  if (closedBy === 'customer' && session.desk_phone) {
    const notice = buildCustomerCloseNotice(session);
    try {
      const sent = await whatsapp.sendMessage(session.desk_phone, notice, {
        chatId: session.desk_chat_id || undefined,
        skipWorkingHours: true,
      });
      const waId = sent?.id?._serialized || sent?.id?.$1 || sent?.id?.id;
      if (waId) {
        try {
          ChatSessions.trackMessage(session.id, 'system_to_desk', waId, notice);
        } catch (_) {}
      }
      MessageLog.add({
        direction: 'out',
        phone: session.desk_phone,
        body: `[session close notify] ${notice}`,
        meta: {
          session_id: session.id,
          session_code: session.session_code,
          closed_by: closedBy,
        },
      });
      console.log(
        `[SessionClose] Close notice sent → company ${session.desk_phone}`
      );
      return { ok: true, notified: true };
    } catch (err) {
      console.error(
        '[SessionClose] Failed to notify company of close:',
        err.message
      );
      return { ok: true, notified: false, error: err.message };
    }
  }

  return { ok: true, notified: false };
}

module.exports = {
  closeSessionWithNotify,
  buildCustomerCloseNotice,
};
